<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
type Node = { id: number; parentId: number | null; code: string; name: string; level: number; enabled: boolean; versionNo: number; versionStatus: string; description: string; updatedAt: string }
const props = defineProps<{ api: string; role: string }>()
const nodes = ref<Node[]>([]); const selectedId = ref<number | null>(null); const loading = ref(false); const error = ref(''); const showForm = ref(false)
const form = ref({ parentId: null as number | null, code: '', name: '', level: 1, description: '' })
const selected = computed(() => nodes.value.find(item => item.id === selectedId.value) || null)
const children = computed(() => nodes.value.filter(item => item.parentId === selectedId.value))
async function request<T>(path: string, options: RequestInit = {}) { const response = await fetch(`${props.api}${path}`, { ...options, headers: { 'Content-Type': 'application/json', 'X-Role': props.role, ...(options.headers || {}) } }); if (!response.ok) throw new Error((await response.text()) || '请求失败'); return response.json() as Promise<T> }
async function load() { loading.value = true; try { nodes.value = await request<Node[]>('/api/categories'); if (!selectedId.value) selectedId.value = nodes.value.find(item => item.level === 1)?.id || null } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
function startCreate(parent: Node | null = null) { form.value = { parentId: parent?.id || null, code: '', name: '', level: parent ? Math.min(parent.level + 1, 3) : 1, description: '' }; showForm.value = true }
async function create() { if (!form.value.code || !form.value.name) { error.value = '请填写分类编码和名称'; return }; try { await request('/api/categories', { method: 'POST', body: JSON.stringify(form.value) }); showForm.value = false; await load() } catch (e) { error.value = (e as Error).message } }
async function toggle(node: Node) { try { await request(`/api/categories/${node.id}/toggle`, { method: 'POST' }); await load() } catch (e) { error.value = (e as Error).message } }
async function publish(node: Node) { try { await request(`/api/categories/${node.id}/publish`, { method: 'POST' }); await load() } catch (e) { error.value = (e as Error).message } }
function name(id: number | null) { return nodes.value.find(item => item.id === id)?.name || '未选择上级' }
onMounted(load)
</script>
<template>
  <section class="category-workspace page-section"><div class="page-header"><div><p class="eyebrow">系统管理 / 合同分类配置</p><h1>合同分类配置</h1><p class="page-desc">维护合同大类、合同类型和子类型。发布后的配置只影响新建或重新选择类型的合同。</p></div><button class="primary-action" @click="startCreate()">＋ 新建分类</button></div><div v-if="error" class="fulfillment-error">{{ error }}<button @click="error=''">关闭</button></div><div class="category-layout"><aside class="panel category-tree"><div class="section-heading"><div><h2>分类目录</h2><p class="section-caption">共 {{ nodes.length }} 个配置项</p></div></div><div v-if="loading" class="inline-empty">正在加载...</div><div v-else class="category-tree-list"><button v-for="item in nodes" :key="item.id" :class="['category-tree-row', `level-${item.level}`, { active: item.id === selectedId, disabled: !item.enabled }]" @click="selectedId=item.id"><span class="tree-mark">{{ item.level === 1 ? '大' : item.level === 2 ? '类' : '子' }}</span><span><b>{{ item.name }}</b><small>{{ item.code }}</small></span></button><div v-if="!nodes.length" class="inline-empty">暂无分类配置</div></div></aside><section class="panel category-detail"><div v-if="selected"><div class="category-detail-head"><div><p class="eyebrow">{{ selected.level === 1 ? '合同大类' : selected.level === 2 ? '合同类型' : '合同子类型' }}</p><h2>{{ selected.name }}</h2><p>{{ selected.code }} · {{ selected.description || '暂无说明' }}</p></div><div class="category-detail-actions"><i class="status-tag">{{ selected.enabled ? '启用' : '停用' }}</i><button class="secondary-action" @click="toggle(selected)">{{ selected.enabled ? '停用' : '启用' }}</button><button v-if="selected.versionStatus !== '已发布'" class="secondary-action" @click="publish(selected)">发布版本</button></div></div><div class="config-summary"><div><span>配置版本</span><b>v{{ selected.versionNo }}</b></div><div><span>版本状态</span><b>{{ selected.versionStatus }}</b></div><div><span>上级分类</span><b>{{ name(selected.parentId) }}</b></div><div><span>下级数量</span><b>{{ children.length }}</b></div></div><div class="category-section"><div class="section-heading"><div><h3>下级分类</h3><p class="section-caption">合同大类不直接作为权限单位，权限按启用的合同类型配置。</p></div><button class="link-button" :disabled="selected.level >= 3" @click="startCreate(selected)">新增下级</button></div><div v-if="children.length" class="child-list"><button v-for="item in children" :key="item.id" @click="selectedId=item.id"><span><b>{{ item.name }}</b><small>{{ item.code }} · {{ item.description || '暂无说明' }}</small></span><i class="status-tag">{{ item.enabled ? '启用' : '停用' }}</i></button></div><div v-else class="inline-empty">暂无下级分类</div></div><div class="category-section"><div class="section-heading"><div><h3>类型规则</h3><p class="section-caption">类型可关联扩展字段、模板、AI 规则、履行规则和角色权限。</p></div></div><div class="rule-grid"><div><b>扩展字段</b><span>待配置</span></div><div><b>可用模板</b><span>待关联</span></div><div><b>AI 审查规则</b><span>待配置</span></div><div><b>履行规则</b><span>待配置</span></div></div></div></div><div v-else class="empty-state"><strong>选择一个分类配置项</strong><span>从左侧目录查看版本、状态和下级配置。</span></div></section></div><section v-if="showForm" class="panel category-form"><div class="section-heading"><div><h2>新建分类</h2><p class="section-caption">按大类、类型、子类型三层结构建立目录。</p></div><button class="ghost-button" @click="showForm=false">取消</button></div><div class="form-grid"><label>上级分类<select v-model="form.parentId"><option :value="null">顶级大类</option><option v-for="item in nodes.filter(node => node.level < 3)" :key="item.id" :value="item.id">{{ item.name }}（{{ item.level === 1 ? '大类' : '类型' }}）</option></select></label><label>层级<select v-model.number="form.level"><option :value="1">合同大类</option><option :value="2">合同类型</option><option :value="3">合同子类型</option></select></label><label>分类编码<input v-model="form.code" placeholder="例如：PROCUREMENT" /></label><label>分类名称<input v-model="form.name" placeholder="例如：采购合同" /></label><label class="full-width">说明<textarea v-model="form.description" rows="3" placeholder="填写该分类的适用范围和业务说明" /></label></div><div class="form-footer"><span class="muted">新建后默认为启用、未发布版本</span><button class="primary-action" @click="create">保存分类</button></div></section></section>
</template>
